function tick(t){let dt=Math.min(.04,(t-last)/1000||.016);last=t;update(dt);draw()}
document.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','Space'].includes(e.code))e.preventDefault();keys[e.code]=true;keys[e.key.toLowerCase()]=true;if((e.code==='Space'||e.code==='Enter')&&(mode==='scene'||mode==='ending'))advance()});document.addEventListener('keyup',e=>{keys[e.code]=false;keys[e.key.toLowerCase()]=false});dialog.addEventListener('pointerdown',()=>{if(mode==='scene'||mode==='ending')advance()});document.querySelectorAll('.mobile button').forEach(b=>{let k=b.dataset.key;const on=e=>{e.preventDefault();touch[k]=true};const off=e=>{e.preventDefault();touch[k]=false};b.addEventListener('pointerdown',on);b.addEventListener('pointerup',off);b.addEventListener('pointerleave',off);b.addEventListener('pointercancel',off)});
requestAnimationFrame(tick);
})();
